import { Injectable, inject } from '@angular/core';
import { HttpClient, HttpEvent, HttpRequest } from '@angular/common/http';
import { Observable, map } from 'rxjs';
import { environment } from '../../environments/environment';

export interface TipoDocumento {
  id?: number;
  clave: string;
  nombre: string;
  requerido?: boolean;
  tab?: string;
  etapa?: 'construccion' | 'operacion' | 'ambas' | null;
  personalidad?: string | null;
}

interface DocumentoEstadoResponse {
  data: {
    id: number;
    firma_serial: string | null;
    fecha_firma: string | null;
  };
}

export interface DocumentoResponse {
  data: {
    id: number;
    nombre_original: string;
    mime_type?: string;
    tamano?: number;
    firma_hash?: string;
    firma_serial?: string;
    fecha_firma?: string;
    estado?: string;
  };
  message?: string;
}

@Injectable({
  providedIn: 'root',
})
export class DocumentoService {
  private readonly http = inject(HttpClient);
  private readonly apiUrl = environment.apiUrl;

  subirDocumento(file: File): Observable<HttpEvent<DocumentoResponse>> {
    const formData = new FormData();
    formData.append('archivo', file);

    const req = new HttpRequest('POST', `${this.apiUrl}/documentos`, formData, {
      reportProgress: true,
      responseType: 'json',
    });

    return this.http.request(req);
  }

  uploadDocumento(file: File): Observable<{ id: number; nombre_original: string }> {
    const formData = new FormData();
    formData.append('archivo', file);

    return this.http
      .post<DocumentoResponse>(`${this.apiUrl}/documentos`, formData)
      .pipe(
        map(res => ({ id: res.data.id, nombre_original: res.data.nombre_original })),
      );
  }

  getTiposDocumento(): Observable<TipoDocumento[]> {
    return this.http
      .get<{ data: TipoDocumento[] }>(`${this.apiUrl}/tipo-documentos`)
      .pipe(map((res) => res.data));
  }

  reemplazarDocumento(folio: string, nombreOriginal: string, file: File): Observable<HttpEvent<DocumentoResponse>> {
    const formData = new FormData();
    formData.append('archivo', file);
    formData.append('nombre_original', nombreOriginal);

    const req = new HttpRequest('POST', `${this.apiUrl}/solicitudes/${folio}/documentos/reemplazar`, formData, {
      reportProgress: true,
      responseType: 'json',
    });

    return this.http.request<DocumentoResponse>(req);
  }

  firmarDocumento(
    documentoId: number,
    signedBytes: Uint8Array,
    serial: string,
    metadata?: string,
  ): Observable<{ id: number; nombre_original: string; firma_serial: string; firma_metadata: string | null; fecha_firma: string }> {
    const blob = new Blob([new Uint8Array(signedBytes)], { type: 'application/pdf' });
    const formData = new FormData();
    formData.append('archivo', blob);
    formData.append('firma_serial', serial);
    if (metadata) {
      formData.append('firma_metadata', metadata);
    }

    return this.http
      .post<{ data: { id: number; nombre_original: string; firma_serial: string; firma_metadata: string | null; fecha_firma: string }; message: string }>(
        `${this.apiUrl}/documentos/${documentoId}/firmar`,
        formData,
      )
      .pipe(
        map(res => res.data),
      );
  }

  getDocumentoEstado(documentoId: number): Observable<{ id: number; firmaSerial: string | null; fechaFirma: string | null }> {
    return this.http.get<DocumentoEstadoResponse>(`${this.apiUrl}/documentos/${documentoId}/estado`).pipe(
      map(res => ({ id: res.data.id, firmaSerial: res.data.firma_serial, fechaFirma: res.data.fecha_firma })),
    );
  }

  downloadDocumento(documentoId: number): Observable<Uint8Array> {
    return this.http
      .get(`${this.apiUrl}/documentos/${documentoId}`, { responseType: 'arraybuffer' })
      .pipe(
        map(arrayBuffer => new Uint8Array(arrayBuffer)),
      );
  }

  deleteDocumento(documentoId: number): Observable<{ message: string }> {
    return this.http.delete<{ message: string }>(`${this.apiUrl}/documentos/${documentoId}`);
  }
}
